// UI conformance suite for framework.echelonfoundry.com (generated by
// research-publisher) against visual-engineering/UI-LAYOUT-INTERACTION@1.0.0.
// Controls resolve by role and accessible name; waits are web-first; actions
// compare observed pre/post state. No coordinates, no fixed sleeps. Defects
// that originate in the generator are expected failures (see UPSTREAM_DEFECTS).
import { expect, test } from "@playwright/test";
import {
  CONTRACT_WIDTHS,
  expectActionOutcome,
  expectLabelIntact,
  inventoryActions,
  measureOverflow,
  recordTabSequence,
  scaleDefaultText,
  settleFontsAndFrames,
  wasFocusedDuringSequence
} from "./forma-conformance/index.mjs";
import { CHROME, RESEARCH_SAMPLE, ROUTES, SURFACES, UPSTREAM_DEFECTS, declaredActionsFor } from "./surfaces.mjs";

const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const annotate = (type, description) => test.info().annotations.push({ type, description });
const pathPattern = destination => new RegExp(`^https?://[^/]+${escape(destination)}$`);
const SCOPES = Object.freeze({
  banner: page => page.getByRole("banner"),
  primary: page => page.getByRole("navigation", { name: "Primary" }),
  main: page => page.getByRole("main")
});
const scoped = (page, scope) => (scope ? SCOPES[scope](page) : page);
const control = (page, action) => scoped(page, action.scope).getByRole(action.control.role, { name: action.control.name, exact: true });
const upstream = key => {
  annotate("uli-upstream", `${key}: ${UPSTREAM_DEFECTS[key]}`);
  test.fail(true, `Known research-publisher defect: ${UPSTREAM_DEFECTS[key]}`);
};

// The generator hides its skip link at left:-999px until focused. The Forma
// helper counts that text as escaping the viewport; it is excluded here only
// after proving it is the focus-revealed skip link (it must come into view on
// focus). Every other escape still fails.
const expectNoOverflowBesidesSkipLink = async page => {
  const report = await measureOverflow(page);
  const escapes = report.escapes.filter(entry => !entry.startsWith('a "Skip to content"'));
  if (escapes.length < report.escapes.length) {
    const skip = page.getByRole("link", { name: "Skip to content", exact: true });
    await skip.focus();
    await expect(skip, "the excluded skip link must come into view on focus").toBeInViewport();
    await skip.blur();
  }
  expect({ pageOverflow: report.reason.split(";")[0], escapes }).toEqual({ pageOverflow: `document scrollWidth ${await page.evaluate(() => document.documentElement.clientWidth)} vs clientWidth ${await page.evaluate(() => document.documentElement.clientWidth)}`, escapes: [] });
};

const headingOf = route => (route.id === "home" ? /^Find the thinking\s*behind the work\.$/ : route.heading);

// --- Every route at every contract width -------------------------------------

for (const width of CONTRACT_WIDTHS) {
  test.describe(`at ${width}px`, () => {
    test.use({ viewport: { width, height: 900 } });
    for (const route of ROUTES) {
      test(`${route.path} renders without overflow, with intact navigation labels`, async ({ page }) => {
        annotate("uli-surface", route.id);
        annotate("uli-surface", "chrome");
        if (route.id === "search" && width === 768) upstream("search-form-overflow-768");
        await page.goto(route.path);
        await expect(page.getByRole("heading", { level: 1 }).first()).toBeVisible();
        await expectNoOverflowBesidesSkipLink(page);
        const nav = SCOPES.primary(page).getByRole("link");
        for (const index of [...Array(await nav.count()).keys()]) await expectLabelIntact(nav.nth(index));
      });

      test(`${route.path} renders only declared actions`, async ({ page }) => {
        annotate("uli-surface", route.id);
        await page.goto(route.path);
        await settleFontsAndFrames(page);
        const declared = declaredActionsFor(route);
        const rendered = await inventoryActions(page.locator("body"));
        const matches = item => declared.some(action => (action.kind === "class" || action.kind === "anchor-class"
          ? item.role === "link" && action.hrefPattern.test(item.href ?? "")
          : action.control.role === item.role && action.control.name === item.name));
        expect(rendered.filter(item => !matches(item)).map(item => `${item.role} "${item.name}" -> ${item.href}`), "ULI-A10: enabled actions without a declared contract").toEqual([]);
        expect(rendered.filter(item => !item.name), "ULI-A06: actions without an accessible name").toEqual([]);
      });
    }
  });

  test.describe(`at ${width}px with 200% text`, () => {
    test.use({ viewport: { width, height: 900 } });
    for (const route of ROUTES) {
      test(`${route.path} reflows without overflow`, async ({ page }) => {
        annotate("uli-surface", route.id);
        if (width <= 390 && route.id !== "not-found") upstream("text-scale-narrow");
        await page.goto(route.path);
        await scaleDefaultText(page, 2);
        await expectNoOverflowBesidesSkipLink(page);
      });
    }
  });
}

// --- One document outline: a single h1 per page ------------------------------

for (const route of ROUTES) {
  test(`${route.path} has exactly one level-one heading`, async ({ page }) => {
    annotate("uli-surface", route.id);
    if (route.id === "research") upstream("research-duplicate-h1");
    await page.goto(route.path);
    await expect(page.getByRole("heading", { level: 1 })).toHaveCount(1);
    if (headingOf(route)) await expect(page.getByRole("heading", { level: 1 })).toHaveText(headingOf(route));
  });
}

test("the home page names this research site", async ({ page }) => {
  annotate("uli-surface", "home");
  upstream("home-kicker-mislabel");
  await page.goto("/");
  await expect(page.getByRole("main")).not.toContainText("Visual Engineering research archive");
});

// --- Destinations of every declared action -----------------------------------

for (const route of ROUTES) {
  test.describe(`${route.path} link destinations`, () => {
    for (const action of declaredActionsFor(route)) {
      test(`${action.surfaceId}/${action.id} is valid`, async ({ page, request }) => {
        annotate("uli-destination", `${action.surfaceId}/${action.id}`);
        await page.goto(route.path);
        if (action.kind === "class" || action.kind === "anchor-class") {
          const hrefs = (await page.locator("a[href]").evaluateAll(elements => elements.map(element => element.getAttribute("href"))))
            .filter(href => action.hrefPattern.test(href));
          expect(hrefs.length, `${action.id} has instances`).toBeGreaterThan(0);
          for (const href of hrefs) {
            if (action.kind === "anchor-class") await expect(page.locator(`[id="${href.slice(1)}"]`), href).toHaveCount(1);
            else expect((await request.get(href)).status(), href).toBe(200);
          }
          return;
        }
        const located = control(page, action);
        if (action.optional && (await located.count()) === 0) {
          // The generator omits the link to the current section on its own
          // page, and renders only "Overview" in the 404 page's header.
          expect(new URL(page.url()).pathname === action.destination || route.id === "not-found", `${action.id} missing on ${route.path}`).toBe(true);
          return;
        }
        await expect(located).toHaveCount(1);
        if (action.kind === "search") {
          await expect(located).toHaveAttribute("type", "submit");
          return;
        }
        await expect(located).toHaveAttribute("href", action.destination);
        if (action.kind === "navigate") expect((await request.get(action.destination)).status(), action.destination).toBe(200);
        if (action.kind === "anchor") await expect(page.locator(action.destination)).toHaveCount(1);
      });
    }
  });
}

// --- ULI-A02/A06: navigation outcomes ----------------------------------------

// Chrome actions start on a document page, where every header link renders.
const START = Object.freeze({ chrome: RESEARCH_SAMPLE });

for (const width of [390, 1280]) {
  test.describe(`navigation outcomes at ${width}px`, () => {
    test.use({ viewport: { width, height: 900 } });
    for (const surface of SURFACES) {
      for (const action of surface.actions.filter(item => ["navigate", "anchor", "class", "anchor-class"].includes(item.kind))) {
        test(`${surface.id}: ${action.id}`, async ({ page }) => {
          annotate("uli-action", `${surface.id}/${action.id}`);
          const from = START[surface.id] ?? ROUTES.find(route => route.id === surface.id)?.path ?? surface.path;
          await page.goto(from);
          if (action.kind === "class" || action.kind === "anchor-class") {
            const href = await SCOPES.main(page).locator("a[href]").evaluateAll((elements, source) =>
              elements.map(element => element.getAttribute("href")).find(value => new RegExp(source).test(value)), action.hrefPattern.source);
            const name = await SCOPES.main(page).locator(`a[href="${href}"]`).first().evaluate(element => element.textContent.replace(/\s+/g, " ").trim());
            const expected = action.kind === "anchor-class" ? `${from}${href}` : href;
            await expectActionOutcome(page, { ruleId: "ULI-A02", action: { role: "link", name, scope: SCOPES.main(page) }, outcome: { kind: "url", expected: pathPattern(expected) } });
            if (action.kind === "anchor-class") await expect(page.locator(`[id="${href.slice(1)}"]`)).toBeInViewport();
            else await expect(page.getByRole("heading", { level: 1 }).first()).toBeVisible();
            return;
          }
          await expectActionOutcome(page, {
            ruleId: "ULI-A02",
            action: { ...action.control, scope: action.scope ? scoped(page, action.scope) : undefined },
            outcome: { kind: "url", expected: pathPattern(action.kind === "anchor" ? `${from}${action.destination}` : action.destination) }
          });
          if (action.kind === "anchor") await expect(page.locator(action.destination)).toBeInViewport();
          if (action.kind === "navigate") await expect(page.getByRole("heading", { level: 1 }).first()).toBeVisible();
        });
      }
    }
  });
}

// --- Search: real client-side results, honest empty state (ULI-A02/A07) -----

const statusLine = page => page.locator("#search-status-line");

test.describe("search", () => {
  test("a query reports and lists its results", async ({ page }) => {
    annotate("uli-action", "search/search-submit");
    await page.goto("/search/");
    await expect(statusLine(page)).toHaveText("");
    await page.getByRole("searchbox", { name: "Query" }).fill("constitution");
    // The status line is a live region without a role or name, so it is
    // addressed by its stable id; pre-state (empty) is asserted above.
    await page.getByRole("button", { name: "Search" }).click();
    await expect(statusLine(page)).toHaveText(/^[1-9]\d* results?$/, { timeout: 20000 });
    const count = Number((await statusLine(page).textContent()).match(/^(\d+)/)[1]);
    await expect(page.locator("#search-results").getByRole("link")).toHaveCount(count);
  });

  test("a query with no match reports zero results and lists nothing", async ({ page }) => {
    annotate("uli-action", "search/search-submit");
    await page.goto("/search/");
    await page.getByRole("searchbox", { name: "Query" }).fill("zzqqxxnotaword");
    await page.getByRole("button", { name: "Search" }).click();
    await expect(statusLine(page)).toHaveText("0 results", { timeout: 20000 });
    await expect(page.locator("#search-results").getByRole("link")).toHaveCount(0);
  });

  test("an artifact-type filter narrows the results", async ({ page }) => {
    annotate("uli-action", "search/search-submit");
    await page.goto("/search/");
    await page.getByRole("searchbox", { name: "Query" }).fill("framework");
    await page.getByRole("button", { name: "Search" }).click();
    await expect(statusLine(page)).toHaveText(/^[1-9]\d* results?$/, { timeout: 20000 });
    const all = Number((await statusLine(page).textContent()).match(/^(\d+)/)[1]);
    await page.getByRole("combobox", { name: "Artifact type" }).selectOption("handoff");
    await page.getByRole("button", { name: "Search" }).click();
    await expect.poll(async () => Number(((await statusLine(page).textContent()).match(/^(\d+) results?$/) ?? [, -1])[1]), { timeout: 20000 })
      .toBeLessThan(all);
  });
});

// --- ULI-A08: keyboard reachability ------------------------------------------

test("every chrome action on a document page is reachable by keyboard", async ({ page }) => {
  annotate("uli-surface", "chrome");
  await page.goto(RESEARCH_SAMPLE);
  await recordTabSequence(page, 10);
  for (const action of CHROME) {
    const located = control(page, action);
    if (action.optional && (await located.count()) === 0) continue;
    expect(await wasFocusedDuringSequence(located), action.id).toBe(true);
  }
});
